with valid as (select id, product_name, category, brand, price, stock_qty, launch_date, tags, supplier_id, price - cost as margin, round(cost * 1.15, 2) as cost_adjusted from products where brand is not null and launch_date > date '2023-08-17') select e.id, e.category, e.brand, e.launch_date, e.tags, e.supplier_id, e.margin, b.supplier_name, b.city, b.rating from valid e inner join suppliers b on e.supplier_id = b.id;
